reference.setup:
{
    run_chisq <- function(m) {
        t <- chisq.test(m, correct = TRUE)
        list(chi_sq = unname(t$statistic), df = unname(t$parameter), p = t$p.value, 
            corrected = isTRUE(nrow(m) == 2 && ncol(m) == 2), low_expected = any(t$expected < 
                5), n = sum(m))
    }
}
